import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const AllListings = () => {
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/listings`)
      .then((res) => res.json())
      .then((data) => {
        const otherListings = data.filter(
          (item) => String(item.user_id) !== String(userId)
        );
        setListings(otherListings);
      })
      .catch((err) => console.error("Error fetching listings:", err));
  }, [userId]);

  const handleBuy = async (item) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/cart`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: userId,
          listing_id: item.id,
          title: item.title,
          price: item.price,
          condition: item.condition,
          description: item.description,
          image: item.image,
        }),
      });

      if (response.ok) {
        alert("Added to cart!");
      } else {
        alert("Failed to add to cart.");
      }
    } catch (err) {
      console.error("Buy error:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div className="all-listings-wrapper">
      <Navbar />
      <main className="all-listings-container">
        <h2 className="section-title">Explore All Listings</h2>

        <div className="listings-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="listing-card" key={item.id}>
                <div className="listing-image-container">
                  {item.image ? (
                    <img src={item.image} alt={item.title} className="listing-image" />
                  ) : (
                    <span className="no-image">No Image</span>
                  )}
                </div>
                <div className="listing-info">
                  <h4>{item.title}</h4>
                  <p>{item.description}</p>
                  <p><strong>Condition:</strong> {item.condition}</p>
                  <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  <button className="buy-btn" onClick={() => handleBuy(item)}>Buy</button>
                </div>
              </div>
            ))
          ) : (
            <p className="empty-text">No listings available from other users.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default AllListings;
